import codecs, hashlib, json, struct, sys, unicodedata
assert sys.version_info[:3] == (3, 14, 7)
assert unicodedata.unidata_version == '16.0.0'
assert sys.platform == 'darwin' and sys.byteorder == 'little'

def digest(rows):
    h = hashlib.sha256()
    for row in rows:
        h.update((json.dumps(row, separators=(',', ':'), ensure_ascii=True) + '\n').encode())
    return h.hexdigest()

def failure(e):
    return ['error', e.encoding, list(e.object), e.start, e.end, e.reason]

def decode_rows(errors):
    for first in range(128, 256):
        for second in range(256):
            try:
                text, consumed = codecs.getdecoder('euc_kr')(bytes([first, second]), errors)
                yield ['ok', list(map(ord, text)), consumed]
            except UnicodeDecodeError as e:
                yield failure(e)

def state(d):
    pending, flags = d.getstate()
    return [list(pending), str(flags)]

def call(d, data, final):
    try:
        result = ['ok', list(map(ord, d.decode(data, final)))]
    except UnicodeDecodeError as e:
        result = failure(e)
    return [result, state(d)]

def split_row(data, split, final, errors):
    d = codecs.getincrementaldecoder('euc_kr')(errors)
    d.setstate((b'', 0x123456789abcdef0))
    row = [call(d, data[:split], False), call(d, data[split:], final), call(d, b'', True)]
    d.reset()
    row.append(state(d))
    return row

def incremental_rows(errors):
    for first in range(256):
        for second in range(256):
            for final in (False, True):
                yield split_row(bytes([first, second]), 1, final, errors)

def hangul_rows(errors):
    for point in range(0xac00, 0xd7a4):
        data = chr(point).encode('euc_kr')
        for split in range(len(data) + 1):
            for final in (False, True):
                yield split_row(data, split, final, errors)

def composition_rows(errors):
    base = bytes.fromhex('a4d4a4a1a4bfa4d4')
    for position in range(8):
        for byte in range(256):
            data = base[:position] + bytes([byte]) + base[position+1:]
            for split in range(9):
                for final in (False, True):
                    yield split_row(data, split, final, errors)
    for size in range(8):
        for split in range(size + 1):
            for final in (False, True):
                yield split_row(base[:size], split, final, errors)

result = {'reference': {'version': sys.version, 'unicode': unicodedata.unidata_version, 'platform': sys.platform, 'byteorder': sys.byteorder}, 'incremental': {}}
for errors in ('strict', 'ignore', 'replace'):
    whole = hashlib.sha256()
    partitions = []
    for first in range(256):
        part = hashlib.sha256()
        count = 0
        for second in range(256):
            for final in (False, True):
                row = split_row(bytes([first, second]), 1, final, errors)
                encoded = (json.dumps(row, separators=(',', ':'), ensure_ascii=True) + '\n').encode()
                part.update(encoded)
                whole.update(encoded)
                count += 1
        partitions.append({'first': first, 'records': count, 'sha256': part.hexdigest()})
    result['incremental'][errors] = {'records': sum(p['records'] for p in partitions), 'sha256': whole.hexdigest(), 'partitions': partitions}
print(json.dumps(result))
